    vector<long long> countBlackBlocks(int m, int n, vector<vector<int>>& coordinates) {
        unordered_map<long long, int> block_counts;
        for (const auto& coord : coordinates) {
            int r = coord[0], c = coord[1];
            for (int dr : {0, -1}) {
                for (int dc : {0, -1}) {
                    int tr = r + dr, tc = c + dc;
                    if (tr >= 0 && tr < m - 1 && tc >= 0 && tc < n - 1) {
                        long long key = ((long long)tr << 32) | (unsigned int)tc;
                        block_counts[key]++;
                    }
                }
            }
        }
        vector<long long> ans(5, 0);
        for (const auto& [k, cnt] : block_counts) {
            ans[cnt]++;
        }
