import java.util.HashMap;
import java.util.Map;

class Solution {
    public long[] countBlackBlocks(int m, int n, int[][] coordinates) {
        Map<Long, Integer> blockCounts = new HashMap<>();
        for (int[] coord : coordinates) {
            int r = coord[0], c = coord[1];
            for (int dr = -1; dr <= 0; dr++) {
                for (int dc = -1; dc <= 0; dc++) {
                    int tr = r + dr, tc = c + dc;
                    if (tr >= 0 && tr < m - 1 && tc >= 0 && tc < n - 1) {
                        long key = (((long) tr) << 32) | (tc & 0xFFFFFFFFL);
                        blockCounts.put(key, blockCounts.getOrDefault(key, 0) + 1);
                    }
                }
            }
        }
        long[] ans = new long[5];
        for (int cnt : blockCounts.values()) {
            ans[cnt]++;
        }
        ans[0] = (long) (m - 1) * (n - 1) - (ans[1] + ans[2] + ans[3] + ans[4]);
        return ans;
    }
}

var countBlackBlocks = function(m, n, coordinates) {
    const blockCounts = new Map();
    for (const [r, c] of coordinates) {
        for (const dr of [0, -1]) {
            for (const dc of [0, -1]) {
                const tr = r + dr, tc = c + dc;
                if (tr >= 0 && tr < m - 1 && tc >= 0 && tc < n - 1) {
                    const key = `${tr},${tc}`;
                    blockCounts.set(key, (blockCounts.get(key) || 0) + 1);
                }
            }
        }
    }
    const ans = [0, 0, 0, 0, 0];
    for (const cnt of blockCounts.values()) {
        ans[cnt]++;
    }
    const totalBlocks = (m - 1) * (n - 1);
    ans[0] = totalBlocks - (ans[1] + ans[2] + ans[3] + ans[4]);
    return ans;
};
